package com.arjunren.hospital.service;
import com.arjunren.hospital.domain.*;import com.arjunren.hospital.dto.Dtos.*;import com.arjunren.hospital.entity.*;import com.arjunren.hospital.exception.DomainException;import com.arjunren.hospital.repository.*;import java.util.*;import org.springframework.data.domain.*;import org.springframework.http.HttpStatus;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class HospitalService{private final UserRepository users;private final DoctorRepository doctors;private final PatientRepository patients;private final AppointmentRepository appointments;private final PasswordEncoder encoder;public HospitalService(UserRepository u,DoctorRepository d,PatientRepository p,AppointmentRepository a,PasswordEncoder e){users=u;doctors=d;patients=p;appointments=a;encoder=e;}@Transactional public DoctorResponse createDoctor(DoctorCreate r,AppUser actor){require(actor,Role.ADMIN);String email=email(r.email()),license=r.licenseNumber().trim().toUpperCase(Locale.ROOT);if(users.findByEmailIgnoreCase(email).isPresent())throw new DomainException(HttpStatus.CONFLICT,"Email already exists");if(doctors.existsByLicenseNumberIgnoreCase(license))throw new DomainException(HttpStatus.CONFLICT,"License number already exists");var u=users.save(new AppUser(email,encoder.encode(r.password()),r.name().trim(),Role.DOCTOR));return DoctorResponse.of(doctors.save(new DoctorProfile(u,license,r.specialty().trim(),r.slotMinutes())));}@Transactional public PatientResponse createPatient(PatientCreate r,AppUser actor){if(actor.getRole()!=Role.ADMIN&&actor.getRole()!=Role.RECEPTIONIST)throw forbidden();String email=email(r.email()),mrn=r.medicalRecordNumber().trim().toUpperCase(Locale.ROOT);if(users.findByEmailIgnoreCase(email).isPresent())throw new DomainException(HttpStatus.CONFLICT,"Email already exists");if(patients.existsByMedicalRecordNumberIgnoreCase(mrn))throw new DomainException(HttpStatus.CONFLICT,"Medical record number already exists");var u=users.save(new AppUser(email,encoder.encode(r.password()),r.name().trim(),Role.PATIENT));return PatientResponse.of(patients.save(new PatientProfile(u,mrn,r.dateOfBirth(),r.phone())));}@Transactional(readOnly=true)public PageResponse<DoctorResponse>doctors(String specialty,int page,int size){var p=doctors.findByActiveTrueAndSpecialtyContainingIgnoreCase(specialty,PageRequest.of(page,size,Sort.by("specialty")));return new PageResponse<>(p.map(DoctorResponse::of).getContent(),page,size,p.getTotalElements(),p.getTotalPages());}@Transactional public AppointmentResponse schedule(AppointmentCreate r,AppUser actor){if(actor.getRole()==Role.DOCTOR)throw forbidden();PatientProfile patient;if(actor.getRole()==Role.PATIENT){patient=patients.findByUserId(actor.getId()).orElseThrow(this::forbidden);if(r.patientId()!=null&&!r.patientId().equals(patient.getId()))throw forbidden();}else{if(r.patientId()==null)throw new DomainException(HttpStatus.UNPROCESSABLE_ENTITY,"patientId is required for staff booking");patient=patients.findById(r.patientId()).orElseThrow(()->new DomainException(HttpStatus.NOT_FOUND,"Patient not found"));}var doctor=doctors.findByIdForUpdate(r.doctorId()).filter(DoctorProfile::isActive).orElseThrow(()->new DomainException(HttpStatus.NOT_FOUND,"Doctor not found"));var end=r.startsAt().plusSeconds(doctor.getSlotMinutes()*60L);if(appointments.conflicts(doctor.getId(),r.startsAt(),end))throw new DomainException(HttpStatus.CONFLICT,"Doctor is unavailable for this time");return AppointmentResponse.of(appointments.save(new Appointment(doctor,patient,r.startsAt(),end,r.reason().trim(),actor)));}@Transactional(readOnly=true)public PageResponse<AppointmentResponse>list(AppUser actor,int page,int size){Pageable p=PageRequest.of(page,size,Sort.by("startsAt"));Page<Appointment>x=actor.getRole()==Role.PATIENT?appointments.findByPatientUserId(actor.getId(),p):actor.getRole()==Role.DOCTOR?appointments.findByDoctorUserId(actor.getId(),p):appointments.findAll(p);return new PageResponse<>(x.map(AppointmentResponse::of).getContent(),page,size,x.getTotalElements(),x.getTotalPages());}@Transactional public AppointmentResponse cancel(Long id,AppUser actor){var a=visibleLock(id,actor);if(a.getStatus()!=AppointmentStatus.SCHEDULED)throw new DomainException(HttpStatus.CONFLICT,"Appointment must be scheduled");a.cancel();return AppointmentResponse.of(a);}@Transactional public AppointmentResponse complete(Long id,CompleteRequest r,AppUser actor){if(actor.getRole()!=Role.DOCTOR&&actor.getRole()!=Role.ADMIN)throw forbidden();var a=visibleLock(id,actor);if(a.getStatus()!=AppointmentStatus.SCHEDULED)throw new DomainException(HttpStatus.CONFLICT,"Appointment must be scheduled");a.complete(r.diagnosis().trim(),r.treatment().trim());return AppointmentResponse.of(a);}@Transactional(readOnly=true)public AppointmentResponse get(Long id,AppUser actor){var a=appointments.findById(id).orElseThrow(()->new DomainException(HttpStatus.NOT_FOUND,"Appointment not found"));checkVisible(a,actor);return AppointmentResponse.of(a);}public long count(AppointmentStatus s){return appointments.countByStatus(s);}private Appointment visibleLock(Long id,AppUser u){var a=appointments.findByIdForUpdate(id).orElseThrow(()->new DomainException(HttpStatus.NOT_FOUND,"Appointment not found"));checkVisible(a,u);return a;}private void checkVisible(Appointment a,AppUser u){if(u.getRole()==Role.PATIENT&&!a.getPatient().getUser().getId().equals(u.getId()))throw forbidden();if(u.getRole()==Role.DOCTOR&&!a.getDoctor().getUser().getId().equals(u.getId()))throw forbidden();}private void require(AppUser u,Role r){if(u.getRole()!=r)throw forbidden();}private DomainException forbidden(){return new DomainException(HttpStatus.FORBIDDEN,"Insufficient permissions");}private String email(String e){return e.trim().toLowerCase(Locale.ROOT);}}
